// Returns { t, face } where face is 'top'|'bottom'|'left'|'right',
// or null if the swept segment (ball center) never enters the expanded AABB.
function sweepBrick(prevX, prevY, curX, curY, ballR, brick) {
  const minX = brick.x - ballR;
  const maxX = brick.x + brick.w + ballR;
  const minY = brick.y - ballR;
  const maxY = brick.y + brick.h + ballR;
  const dx = curX - prevX;
  const dy = curY - prevY;

  let tEnter = 0;
  let tExit = 1;
  let candidateAxis = null;

  // X axis
  if (dx === 0) {
    if (prevX < minX || prevX > maxX) return null;
  } else {
    const t1 = (minX - prevX) / dx;
    const t2 = (maxX - prevX) / dx;
    const tLow = Math.min(t1, t2);
    const tHigh = Math.max(t1, t2);
    if (tEnter < tLow) { tEnter = tLow; candidateAxis = dx > 0 ? 'left' : 'right'; }
    tExit = Math.min(tExit, tHigh);
    if (tEnter > tExit) return null;
  }

  // Y axis
  if (dy === 0) {
    if (prevY < minY || prevY > maxY) return null;
  } else {
    const t1 = (minY - prevY) / dy;
    const t2 = (maxY - prevY) / dy;
    const tLow = Math.min(t1, t2);
    const tHigh = Math.max(t1, t2);
    if (tEnter < tLow) { tEnter = tLow; candidateAxis = dy > 0 ? 'top' : 'bottom'; }
    tExit = Math.min(tExit, tHigh);
    if (tEnter > tExit) return null;
  }

  if (tEnter < 0) tEnter = 0;
  if (tEnter > tExit) return null;
  if (tEnter > 1) return null;

  return { t: tEnter, face: candidateAxis };
}
```

