```
const EPS = 1e-6;

function sweptHit(px, py, x, y, r, brick) {
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = x - px;
  const dy = y - py;

  // If it doesn't move this frame, only a point-in-rect test is possible.
  if (dx === 0 && dy === 0) {
    if (px < minX || px > maxX || py < minY || py > maxY) return null;
    return { t: 0, face: penetrationFace({ x: px, y: py, r }, brick) };
  }

  let tEnter = 0;
  let tExit = 1;
  let enterX = -Infinity;
  let enterY = -Infinity;
  let movedX = dx !== 0;
  let movedY = dy !== 0;

  if (dx === 0) {
    if (px < minX || px > maxX) return null;
  } else {
    const t1 = (minX - px) / dx;
    const t2 = (maxX - px) / dx;
    const lo = Math.min(t1, t2);
    const hi = Math.max(t1, t2);
    enterX = lo;
    tEnter = Math.max(tEnter, lo);
    tExit = Math.min(tExit, hi);
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (py < minY || py > maxY) return null;
  } else {
    const t1 = (minY - py) / dy;
    const t2 = (maxY - py) / dy;
    const lo = Math.min(t1, t2);
    const hi = Math.max(t1, t2);
    enterY = lo;
    tEnter = Math.max(tEnter, lo);
    tExit = Math.min(tExit, hi);
    if (tEnter > tExit) return null;
  }

  if (tEnter < 0) {
    // started inside the expanded rect: treat as an immediate overlap.
    return { t: 0, face: penetrationFace({ x, y, r }, brick) };
  }
  if (tEnter > 1) return null;

  // Which slab was entered last → that's the face hit. Nearly-equal = corner.
  if (movedX && movedY && Math.abs(enterX - enterY) < EPS) {
    return { t: tEnter, face: 'corner' };
  }
  if (!movedY || (movedX && enterX > enterY)) {
    const face = dx > 0 ? 'left' : 'right';
    return { t: tEnter, face };
  }
  const face = dy > 0 ? 'top' : 'bottom';
  return { t: tEnter, face };
}
```

